export const platformPersonAuthSubjects = pgTable('platform_person_auth_subjects',{id:uuid('id').defaultRandom().primaryKey(),personId:uuid('person_id').notNull().references(()=>platformPersons.id,{onDelete:'restrict'}),authSubject:text('auth_subject').notNull(),provider:text('provider').notNull(),providerVersion:smallint('provider_version').notNull().default(1),status:text('status').notNull().default('active'),verifiedAt:timestamp('verified_at',{withTimezone:true}).notNull().defaultNow(),createdAt:timestamp('created_at',{withTimezone:true}).notNull().defaultNow(),createdBy:text('created_by').notNull(),revokedAt:timestamp('revoked_at',{withTimezone:true}),revokedBy:text('revoked_by')},t=>[uniqueIndex('platform_person_auth_subject_owner_unique').on(t.provider,t.authSubject),index('platform_person_auth_subject_person_active_idx').on(t.personId,t.createdAt.desc()).where(sql`${t.status}='active'`),check('platform_person_auth_subject_canonical',sql`${t.authSubject}=btrim(${t.authSubject}) AND char_length(${t.authSubject}) BETWEEN 1 AND 500 AND ${t.authSubject} !~ '[[:cntrl:]]'`),check('platform_person_auth_provider_check',sql`${t.provider}=btrim(${t.provider}) AND ${t.provider} ~ '^[a-z][a-z0-9.-]{0,63}$'`),check('platform_person_auth_provider_version_check',sql`${t.providerVersion} BETWEEN 1 AND 32767`),check('platform_person_auth_status_check',sql`${t.status} IN ('active','revoked')`),check('platform_person_auth_revocation_check',sql`(${t.status}='active' AND ${t.revokedAt} IS NULL AND ${t.revokedBy} IS NULL) OR (${t.status}='revoked' AND ${t.revokedAt} IS NOT NULL AND ${t.revokedBy} IS NOT NULL)`),check('platform_person_auth_actor_check',sql`char_length(${t.createdBy}) BETWEEN 1 AND 120 AND (${t.revokedBy} IS NULL OR char_length(${t.revokedBy}) BETWEEN 1 AND 120)`)]);
export const trainingLinkTransactions = pgTable('training_link_transactions', {
  transactionId: uuid('transaction_id').defaultRandom().primaryKey(),
  personId: uuid('person_id').notNull().references(() => platformPersons.id, { onDelete: 'restrict' }),
  authSubjectLinkId: uuid('auth_subject_link_id').notNull().references(() => platformPersonAuthSubjects.id, { onDelete: 'restrict' }),
  requestId: uuid('request_id').notNull(),
  requestHash: char('request_hash', { length: 64 }).notNull(),
  state: text('state').notNull().default('pending'),
  nonceHash: char('nonce_hash', { length: 64 }).notNull(),
  verifiedTrainingUserId: text('verified_training_user_id'),
  audience: text('audience').notNull(),
  purpose: text('purpose').notNull(),
  expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  verifiedAt: timestamp('verified_at', { withTimezone: true }),
  sourceReceiptId: uuid('source_receipt_id'),
  consumedAt: timestamp('consumed_at', { withTimezone: true }),
  cancelledAt: timestamp('cancelled_at', { withTimezone: true }),
  failureReason: text('failure_reason'),
  version: integer('version').notNull().default(1),
}, (t) => [
  uniqueIndex('training_link_transactions_request_id_key').on(t.requestId),
  uniqueIndex('training_link_transactions_nonce_hash_key').on(t.nonceHash),
  uniqueIndex('training_link_transactions_source_receipt_key').on(t.sourceReceiptId),
  index('training_link_transactions_person_state_idx').on(t.personId, t.state, t.expiresAt),
  check('training_link_transactions_state_check', sql`${t.state} IN ('pending','verified','consumed','expired','cancelled')`),
  check('training_link_transactions_hash_check', sql`${t.requestHash} ~ '^[0-9a-f]{64}$' AND ${t.nonceHash} ~ '^[0-9a-f]{64}$'`),
  check('training_link_tx_verified_subject_canonical_check', sql`${t.verifiedTrainingUserId} IS NULL OR (${t.verifiedTrainingUserId}=btrim(${t.verifiedTrainingUserId}) AND char_length(${t.verifiedTrainingUserId}) BETWEEN 1 AND 200 AND ${t.verifiedTrainingUserId} !~ '[[:cntrl:]]')`),
  check('training_link_tx_verified_subject_state_check', sql`(${t.state}='pending' AND ${t.verifiedTrainingUserId} IS NULL) OR (${t.state} IN ('verified','consumed') AND ${t.verifiedTrainingUserId} IS NOT NULL) OR ${t.state} IN ('expired','cancelled')`),
  check('training_link_transactions_audience_check', sql`${t.audience}='2j-training-account-link'`),
  check('training_link_transactions_purpose_check', sql`${t.purpose}='training-account-link'`),
  check('training_link_transactions_ttl_check', sql`${t.expiresAt}>${t.createdAt} AND ${t.expiresAt}<=${t.createdAt}+interval '5 minutes'`),
  check('training_link_transactions_state_timestamps_check', sql`(${t.state}='pending' AND ${t.verifiedAt} IS NULL AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='verified' AND ${t.verifiedAt} IS NOT NULL AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='consumed' AND ${t.verifiedAt} IS NOT NULL AND ${t.consumedAt} IS NOT NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='expired' AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NULL) OR (${t.state}='cancelled' AND ${t.consumedAt} IS NULL AND ${t.cancelledAt} IS NOT NULL)`),
  check('training_link_transactions_failure_check', sql`${t.failureReason} IS NULL OR (${t.state} IN ('expired','cancelled') AND char_length(${t.failureReason}) BETWEEN 1 AND 80)`),
  check('training_link_transactions_version_check', sql`${t.version}>0`),
  check('training_link_transactions_receipt_state_check', sql`${t.sourceReceiptId} IS NULL OR ${t.state} IN ('verified','consumed','expired')`),
]);

export const storeProducts = pgTable('store_products', { id:uuid('id').defaultRandom().primaryKey(),centerKey:text('center_key').notNull(),category:text('category').notNull(),name:text('name').notNull(),description:text('description').notNull(),active:boolean('active').notNull(),createdAt:timestamp('created_at',{withTimezone:true}).notNull(),updatedAt:timestamp('updated_at',{withTimezone:true}).notNull(),createdBy:text('created_by').notNull(),updatedBy:text('updated_by').notNull() },t=>[index('store_products_active_catalog_idx').on(t.centerKey,t.category,t.name,t.id).where(sql`${t.active}`)]);
export const storeProductVariants = pgTable('store_product_variants', { id:uuid('id').defaultRandom().primaryKey(),productId:uuid('product_id').notNull().references(()=>storeProducts.id,{onDelete:'restrict'}),sku:text('sku'),label:text('label').notNull(),size:text('size'),flavor:text('flavor'),priceCents:bigint('price_cents',{mode:'number'}).notNull(),active:boolean('active').notNull(),stockTracked:boolean('stock_tracked').notNull(),createdAt:timestamp('created_at',{withTimezone:true}).notNull(),updatedAt:timestamp('updated_at',{withTimezone:true}).notNull(),createdBy:text('created_by').notNull(),updatedBy:text('updated_by').notNull() },t=>[index('store_variants_product_idx').on(t.productId,t.active,t.label,t.id)]);
export const storeSales = pgTable('store_sales', { id:uuid('id').defaultRandom().primaryKey(),centerKey:text('center_key').notNull(),clientId:uuid('client_id').notNull().references(()=>clients.id,{onDelete:'restrict'}),cashSessionId:uuid('cash_session_id').references(()=>economicCashSessions.id,{onDelete:'restrict'}),status:text('status').notNull(),paymentState:text('payment_state').notNull(),paymentMethod:text('payment_method'),subtotalCents:bigint('subtotal_cents',{mode:'number'}).notNull(),totalCents:bigint('total_cents',{mode:'number'}).notNull(),note:text('note').notNull(),idempotencyKey:uuid('idempotency_key').notNull(),requestHash:char('request_hash',{length:64}).notNull(),createdAt:timestamp('created_at',{withTimezone:true}).notNull(),createdBy:text('created_by').notNull(),voidedAt:timestamp('voided_at',{withTimezone:true}),voidedBy:text('voided_by') },t=>[uniqueIndex('store_sales_center_key_idempotency_key_key').on(t.centerKey,t.idempotencyKey),index('store_sales_client_history_idx').on(t.clientId,t.createdAt.desc(),t.id.desc()),index('store_sales_cash_session_idx').on(t.cashSessionId,t.createdAt,t.id).where(sql`${t.cashSessionId} IS NOT NULL`)]);
export const storeSaleLines = pgTable('store_sale_lines', { id:uuid('id').defaultRandom().primaryKey(),saleId:uuid('sale_id').notNull().references(()=>storeSales.id,{onDelete:'restrict'}),variantId:uuid('variant_id').notNull().references(()=>storeProductVariants.id,{onDelete:'restrict'}),productNameSnapshot:text('product_name_snapshot').notNull(),variantLabelSnapshot:text('variant_label_snapshot').notNull(),skuSnapshot:text('sku_snapshot'),unitPriceCents:bigint('unit_price_cents',{mode:'number'}).notNull(),quantity:integer('quantity').notNull(),lineTotalCents:bigint('line_total_cents',{mode:'number'}).notNull() },t=>[index('store_sale_lines_sale_idx').on(t.saleId,t.id)]);
export const storeSaleCashMovements = pgTable('store_sale_cash_movements', { id:uuid('id').defaultRandom().primaryKey(),saleId:uuid('sale_id').notNull().references(()=>storeSales.id,{onDelete:'restrict'}),cashSessionId:uuid('cash_session_id').notNull().references(()=>economicCashSessions.id,{onDelete:'restrict'}),movementType:text('movement_type').notNull(),paymentMethod:text('payment_method'),amountCents:bigint('amount_cents',{mode:'number'}).notNull(),reason:text('reason').notNull(),actorId:text('actor_id').notNull(),occurredAt:timestamp('occurred_at',{withTimezone:true}).notNull() },t=>[uniqueIndex('store_sale_cash_movements_sale_id_key').on(t.saleId),index('store_sale_cash_movements_session_idx').on(t.cashSessionId,t.occurredAt,t.id)]);
export const storeInventoryMovements = pgTable('store_inventory_movements', { id:uuid('id').defaultRandom().primaryKey(),variantId:uuid('variant_id').notNull().references(()=>storeProductVariants.id,{onDelete:'restrict'}),quantityDelta:integer('quantity_delta').notNull(),movementType:text('movement_type').notNull(),reason:text('reason').notNull(),actorId:text('actor_id').notNull(),saleId:uuid('sale_id').references(()=>storeSales.id,{onDelete:'restrict'}),occurredAt:timestamp('occurred_at',{withTimezone:true}).notNull() },t=>[index('store_inventory_variant_timeline_idx').on(t.variantId,t.occurredAt.desc(),t.id.desc())]);
export const storeProductMedia = pgTable('store_product_media', { id:uuid('id').defaultRandom().primaryKey(),productId:uuid('product_id').notNull().references(()=>storeProducts.id,{onDelete:'restrict'}),objectKey:text('object_key').notNull().unique(),mimeType:text('mime_type').notNull(),sizeBytes:integer('size_bytes').notNull(),position:integer('position').notNull(),isPrimary:boolean('is_primary').notNull(),createdAt:timestamp('created_at',{withTimezone:true}).notNull(),createdBy:text('created_by').notNull() },t=>[index('store_product_media_product_idx').on(t.productId,t.position)]);
